"""
Moxon rectangle for LoRa 868 MHz - directional PCB antenna, about 6 dBi and > 20 dB front/back ratio.

Single-sided board (home etching or JLCPCB), the only part is the coax feed:

  * AE1 is the antenna copper itself, one footprint generated by layout.py from moxon-868-dims.json
    (written by sim.py): pad 1 / pad 2 are the two halves of the driven element, the reflector is
    copper without a net. Feed impedance is close to 50 Ohm, no matching network.
  * J1 are the solder pads for a 50 Ohm pigtail (RG316 / RG174, other end SMA) right at the feed gap:
    centre conductor to pad 1, shield to pad 2. The cable runs straight back along the centre line,
    across the reflector, so it couples as little as possible into the antenna.

Run with:  python board.py   (writes the netlist; schematic.py draws the schematic)
"""

from pathlib import Path

from skidl import *

HERE = Path(__file__).resolve().parent
PROJECT = "moxon-868"
set_default_tool(KICAD9)
footprint_search_paths[KICAD9].append(str(HERE))

# Parts ---------------------------------------------------------------------------------------
ant = Part("Device", "Antenna_Dipole", ref="AE1", value="Moxon 868MHz", footprint=f"{PROJECT}:Moxon_868")
feed = Part("Connector", "Conn_Coaxial", ref="J1", value="RG316 pigtail", footprint=f"{PROJECT}:CoaxFeed_Gap2mm")

# Nets ----------------------------------------------------------------------------------------
Net("RF").connect(feed["In"], ant[1])
Net("RF_SHIELD").connect(feed["Ext"], ant[2])

# Output --------------------------------------------------------------------------------------
if __name__ == "__main__":
    ERC()
    generate_netlist(file_=str(HERE / f"{PROJECT}.net"))
